    def __init__(self, multiworld: "MultiWorld", player: int):
        super().__init__(multiworld, player)
        # Game-specific world attributes
        self.world_class_name = 'RaftWorld'
        self.extraItemNamePool = ['Resource Pack: 1 Plank', 'Resource Pack: 2 Plank', 'Resource Pack: 3 Plank', 'Resource Pack: 4 Plank', 'Resource Pack: 5 Plank', 'Resource Pack: 1 Plastic', 'Resource Pack: 2 Plastic', 'Resource Pack: 3 Plastic', 'Resource Pack: 4 Plastic', 'Resource Pack: 5 Plastic', 'Resource Pack: 1 Clay', 'Resource Pack: 2 Clay', 'Resource Pack: 3 Clay', 'Resource Pack: 4 Clay', 'Resource Pack: 5 Clay', 'Resource Pack: 1 Stone', 'Resource Pack: 2 Stone', 'Resource Pack: 3 Stone', 'Resource Pack: 4 Stone', 'Resource Pack: 5 Stone', 'Resource Pack: 1 Scrap', 'Resource Pack: 2 Scrap', 'Resource Pack: 3 Scrap', 'Resource Pack: 4 Scrap', 'Resource Pack: 5 Scrap', 'Resource Pack: 1 SeaVine', 'Resource Pack: 2 SeaVine', 'Resource Pack: 3 SeaVine', 'Resource Pack: 4 SeaVine', 'Resource Pack: 5 SeaVine', 'Resource Pack: 1 Thatch', 'Resource Pack: 2 Thatch', 'Resource Pack: 3 Thatch', 'Resource Pack: 4 Thatch', 'Resource Pack: 5 Thatch', 'Resource Pack: 1 Sand', 'Resource Pack: 2 Sand', 'Resource Pack: 3 Sand', 'Resource Pack: 4 Sand', 'Resource Pack: 5 Sand', 'Resource Pack: 1 Raw_Beet', 'Resource Pack: 2 Raw_Beet', 'Resource Pack: 3 Raw_Beet', 'Resource Pack: 4 Raw_Beet', 'Resource Pack: 5 Raw_Beet', 'Resource Pack: 1 Raw_Potato', 'Resource Pack: 2 Raw_Potato', 'Resource Pack: 3 Raw_Potato', 'Resource Pack: 4 Raw_Potato', 'Resource Pack: 5 Raw_Potato', 'Resource Pack: 1 MetalOre', 'Resource Pack: 2 MetalOre', 'Resource Pack: 3 MetalOre', 'Resource Pack: 4 MetalOre', 'Resource Pack: 5 MetalOre', 'Resource Pack: 1 TitaniumOre', 'Resource Pack: 2 TitaniumOre', 'Resource Pack: 3 TitaniumOre', 'Resource Pack: 4 TitaniumOre', 'Resource Pack: 5 TitaniumOre', 'Resource Pack: 1 CopperOre', 'Resource Pack: 2 CopperOre', 'Resource Pack: 3 CopperOre', 'Resource Pack: 4 CopperOre', 'Resource Pack: 5 CopperOre', 'Resource Pack: 1 ExplosiveGoo', 'Resource Pack: 2 ExplosiveGoo', 'Resource Pack: 3 ExplosiveGoo', 'Resource Pack: 4 ExplosiveGoo', 'Resource Pack: 5 ExplosiveGoo']
        self.world_description = "Raft is a flooded world exploration game. You're stranded on a small raft in the middle of the\nocean, and you must survive on trash floating by you on the top of the water and around/on any\nislands that you come across."
